package edu.pe.cibertec.saibm.inventario.infrastructure.messaging; import java.time.Instant; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import com.fasterxml.jackson.databind.ObjectMapper; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.port.out.InboxPort; @Component public class InventoryMessageListener {private final InventoryUseCase use;private final InboxPort inbox;private final ObjectMapper mapper;public InventoryMessageListener(InventoryUseCase u,InboxPort i,ObjectMapper m){use=u;inbox=i;mapper=m;}@RabbitListener(queues=RabbitConfig.HOLD_QUEUE)@Transactional public void hold(String json)throws Exception{handle(mapper.readValue(json,EventEnvelope.class),false);}@RabbitListener(queues=RabbitConfig.RELEASE_QUEUE)@Transactional public void release(String json)throws Exception{handle(mapper.readValue(json,EventEnvelope.class),true);}private void handle(EventEnvelope e,boolean release){if(e.eventVersion()!=1)throw new IllegalArgumentException("Unsupported inventory event version");if(!inbox.firstSeen(e.eventId(),e.eventType()))return;var p=e.payload();if(release)use.release((String)p.get("bookId"),(String)p.get("operationKey"),e.correlationId());else use.hold((String)p.get("bookId"),((Number)p.get("quantity")).intValue(),Instant.parse((String)p.get("expiresAt")),(String)p.get("operationKey"),e.correlationId());}}
